from __future__ import annotations

"""Clean-room redis.client — Redis + Pipeline(Redis) like redis 5/6/8."""

from redis.commands import CoreCommands


class Redis(CoreCommands):
    def pipeline(self, transaction=True, shard_hint=None) -> "Pipeline":
        return Pipeline(self)

    def execute_command(self, *args, **kwargs):
        pass


class Pipeline(Redis):
    """Buffers commands; only execute() performs IO."""

    def __init__(self, connection_pool=None, *args, **kwargs):
        # Accept Redis instance or nothing — keep construction simple for stubs.
        self.command_stack = []

    def execute(self, raise_on_error=True):
        pass
